def start_withp(words_list):
    """
    Return two words from a list of words starting with letter 'p'.

    Args:
        words_list: List of strings containing words separated by spaces

    Returns:
        Tuple of two words starting with 'p'
    """
    p_words = []
    for item in words_list:
        for word in item.split():
            if word.lower().startswith('p'):
                p_words.append(word)
                if len(p_words) == 2:
                    return tuple(p_words)
    return tuple(p_words[:2])


