def get_median(list1: list[int], list2: list[int], n: int) -> float:
    """Find the median of two sorted lists of the same size using Claude API."""
    client = anthropic.Anthropic()

    message = client.messages.create(
        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        messages=[
            {
                "role": "user",
                "content": f"""Write a Python function that finds the median of two sorted lists of the same size.

The function should:
1. Take two sorted lists and their size as parameters
2. Merge them efficiently without sorting
3. Return the median value as a float

Test case:
- list1 = {list1}
- list2 = {list2}
- n = {n}
- Expected result: 16.0

Please provide just the function code, nothing else."""
            }
        ]
    )

    response_text = message.content[0].text

    lines = response_text.strip().split('\n')
    code_lines = []
    in_function = False

    for line in lines:
        if line.strip().startswith('def '):
            in_function = True
        if in_function:
            code_lines.append(line)

    function_code = '\n'.join(code_lines)

    local_scope = {}
    exec(function_code, local_scope)

    median_func = local_scope['get_median']

    return median_func(list1, list2, n)


