        model="claude-3-5-sonnet-20241022",
        max_tokens=1024,
        messages=[
            {
                "role": "user",
                "content": f"""Write Python code to check whether the count of divisors of {n} is even.

The function should:
1. Count all divisors of {n}
2. Return True if the count is even, False otherwise

Provide only the Python code without explanations."""
            }
        ]
    )

    code_content = message.content[0].text

    local_vars = {}
    exec(code_content, local_vars)

    if 'is_even_divisor_count' in local_vars:
        return local_vars['is_even_divisor_count'](n)
