def get_max_sum(n):
    memo = {}

    def f(x):
        if x == 0:
            return 0
        if x in memo:
            return memo[x]

        value = max(
            f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5),
            x
        )
        memo[x] = value
        return value

    return f(n)


