def get_max_sum(n):
    memo = {}

    def helper(num):
        if num in memo:
            return memo[num]

        # Base case: if num is 0, return 0
        if num == 0:
            return 0

        # Option 1: Keep the number as-is
        max_sum = num

        # Option 2: Try dividing by 2, 3, 4, or 5
        for divisor in [2, 3, 4, 5]:
            if num % divisor == 0:
                # Recursively get max sum for the quotient and add the remainder handling
                quotient = num // divisor
                # When we divide by divisor, we get quotient repeated divisor times
                # But we need to consider: should we divide or keep as is?
                current_sum = helper(quotient) * divisor
                max_sum = max(max_sum, current_sum)

        memo[num] = max_sum
        return max_sum

    return helper(n)


# Test the function
if __name__ == "__main__":
    result = get_max_sum(60)
    print(f"get_max_sum(60) = {result}")
    assert result == 106, f"Expected 106, got {result}"
    print("Test passed!")

def dict_depth(d):
    if not isinstance(d, dict) or not d:
        return 1

    max_depth = 0
