def tuple_to_dict(t):
    """
    Convert a tuple into a dictionary by pairing adjacent elements.
    Odd-indexed elements (1, 3, 5, ...) become keys and even-indexed elements
    following them (2, 4, 6, ...) become their corresponding values.
    """
    result = {}
    for i in range(1, len(t), 2):
        if i + 1 < len(t):
            result[t[i]] = t[i + 1]
    return result


