def reverse_vowels(s: str) -> str:
    vowels = "aeiouAEIOU"
    chars = list(s)
    vowel_chars = []
    vowel_positions = []

    for i, char in enumerate(chars):
        if char in vowels:
            vowel_chars.append(char)
            vowel_positions.append(i)

    vowel_chars.reverse()

    for i, pos in enumerate(vowel_positions):
        chars[pos] = vowel_chars[i]

    return ''.join(chars)


if __name__ == "__main__":
    assert reverse_vowels("Python") == "Python"
    print("Test passed!")
    print(f"reverse_vowels('Python') = '{reverse_vowels('Python')}'")
    print(f"reverse_vowels('hello') = '{reverse_vowels('hello')}'")
    print(f"reverse_vowels('aeiou') = '{reverse_vowels('aeiou')}'")

def reverse_vowels(s: str) -> str:
    vowels = "aeiouAEIOU"
    s_list = list(s)
    left = 0
    right = len(s) - 1

    while left < right:
        while left < right and s_list[left] not in vowels:
            left += 1
        while left < right and s_list[right] not in vowels:
            right -= 1

        if left < right:
            s_list[left], s_list[right] = s_list[right], s_list[left]
            left += 1
            right -= 1

    return ''.join(s_list)


if __name__ == "__main__":
    assert reverse_vowels("Python") == "Python"
    assert reverse_vowels("hello") == "holle"
    assert reverse_vowels("aeiou") == "uoiea"
    assert reverse_vowels("bcdfg") == "bcdfg"
    assert reverse_vowels("race car") == "race car"
    print("All assertions passed!")

