def first_non_repeating_character(s):
    """
    Find and return the first character in a string that appears only once,
    or return None if all characters are repeated.
    """
    char_count = {}

    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    for char in s:
        if char_count[char] == 1:
            return char

    return None


