def get_Inv_Count(arr):
    """
    Count inversions in an array.
    An inversion is a pair of indices (i, j) where i < j but arr[i] > arr[j].
    """
    count = 0
    n = len(arr)

    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                count += 1

    return count


