def count_Substrings(s: str) -> int:
    count = 0
    n = len(s)

    for i in range(n):
        digit_sum = 0
        for j in range(i, n):
            digit_sum += int(s[j])
            substring_length = j - i + 1
            if digit_sum == substring_length:
                count += 1

    return count

