def max_length(lst):
    """
    Find and return the longest sublist from a list of lists along with its length as a tuple.

    Args:
        lst: A list of lists

    Returns:
        A tuple containing (length, longest_sublist)
    """
    if not lst:
        return (0, [])

    max_len = 0
    longest = []

    for sublist in lst:
        if len(sublist) > max_len:
            max_len = len(sublist)
            longest = sublist

    return (max_len, longest)


