def tuple_intersection(list1, list2):
    """
    Find the intersection of tuples from two lists by normalizing them to a canonical sorted form.
    Returns the common tuples regardless of element order.
    """
    # Convert each tuple to a sorted tuple (canonical form) and create sets
    set1 = {tuple(sorted(t)) for t in list1}
    set2 = {tuple(sorted(t)) for t in list2}

    # Find intersection of the two sets
    return set1 & set2


# Test with the provided assertion
