def extract_even(nested_tuple):
    """
    Recursively filter even numbers from a nested tuple while preserving 
    the nested structure and excluding empty nested tuples.
    """
    result = []

    for item in nested_tuple:
        if isinstance(item, tuple):
            # Recursively process nested tuples
            filtered_nested = extract_even(item)
            # Only include non-empty nested tuples
            if filtered_nested:
                result.append(filtered_nested)
        elif isinstance(item, int) and item % 2 == 0:
            # Include even numbers
            result.append(item)

    return tuple(result)


# Test with the provided assertion
assert extract_even((4, 5, (7, 6, (2, 4)), 6, 8)) == (4, (6, (2, 4)), 6, 8)
print("Test passed!")

