def divisible_by_digits(start, end):
    result = []
    for num in range(start, end + 1):
        str_num = str(num)
        # Skip numbers containing 0
        if '0' in str_num:
            continue
        # Check if number is divisible by all its digits
        is_valid = True
        for digit in str_num:
            digit_int = int(digit)
            if num % digit_int != 0:
                is_valid = False
                break
        if is_valid:
            result.append(num)
    return result


