def unique_sublists(lists):
    """
    Count lists within a list. Returns a dictionary where every list is converted 
    to a tuple and the value is the number of its occurrences in the original list.
    """
    count_dict = {}
    for sublist in lists:
        tuple_key = tuple(sublist)
        count_dict[tuple_key] = count_dict.get(tuple_key, 0) + 1
    return count_dict


