def unique_sublists(sublists):
    """
    Convert a list of sublists into tuples and return a dictionary 
    containing each unique tuple mapped to its occurrence count.
    """
    tuple_count = {}
    for sublist in sublists:
        tuple_key = tuple(sublist)
        if tuple_key in tuple_count:
            tuple_count[tuple_key] += 1
        else:
            tuple_count[tuple_key] = 1
    return tuple_count


